from pathlib import Path
import hashlib,json,subprocess
root=Path(__file__).resolve().parent
base="473c7b26eccf1e7b77c4c8e2d4c7f57ccb840afe"
head=subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()
required=["finalfix-runtime-owner-current","finalfix-baseline21","finalfix-final-shared-closure","finalfix-committed-static","finalfix-committed-main-format","finalfix-committed-session-format","finalfix-committed-fixture-format","finalfix-committed-whitespace","finalfix-processes-exited"]
